package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.regex.Pattern;
import java.util.regex.PatternSyntaxException;
import org.jsoup.helper.StringUtil;
import org.jsoup.helper.Validate;
import org.jsoup.nodes.DataNode;
import org.jsoup.nodes.Element;
import org.jsoup.nodes.Node;
import org.jsoup.nodes.Tag;
import org.jsoup.nodes.TextNode;
import org.jsoup.parser.Parser;
import org.jsoup.parser.Tag;
import org.jsoup.select.Collector;
import org.jsoup.select.Elements;
import org.jsoup.select.Evaluator;
import org.jsoup.select.Selector;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertSame;

public class Element_clone_TriageGen0Test {
    @Test
    public void testClone() {
        Element element = new Element(Tag.valueOf("tag"), "baseUri", Parser.parseBodyFragment("<tag></tag>"));
        Element clone = element.clone();
        element.classNames();
        assertEquals(element, clone);
        assertSame(element.getClass(), clone.getClass());
    }

    @Test
    public void testCloneNull() {
        Element element = null;
        assertThrows(NullPointerException.class, () -> element.clone());
    }

    @Test
    public void testCloneText() {
        Element element = new Element(Tag.valueOf("tag"), "baseUri", Parser.parseBodyFragment("<tag></tag>"));
        TextNode textNode = new TextNode("text");
        element.appendChild(textNode);
        Element clone = element.clone();
        clone.classNames();
        assertEquals(element, clone);
        assertSame(element.getClass(), clone.getClass());
    }

    @Test
    public void testCloneData() {
        Element element = new Element(Tag.valueOf("tag"), "baseUri", Parser.parseBodyFragment("<tag></tag>"));
        DataNode dataNode = new DataNode("data");
        element.appendChild(dataNode);
        Element clone = element.clone();
        clone.classNames();
        assertEquals(element, clone);
        assertSame(element.getClass(), clone.getClass());
    }

    @Test
    public void testCloneTag() {
        Element element = new Element(Tag.valueOf("tag"), "baseUri", Parser.parseBodyFragment("<tag></tag>"));
        Element clone = element.clone();
        clone.classNames();
        assertEquals(element, clone);
        assertSame(element.getClass(), clone.getClass());
    }

    @Test
    public void testCloneSuperClone() {
        Element element = new Element(Tag.valueOf("tag"), "baseUri", Parser.parseBodyFragment("<tag></tag>"));
        Element clone = (Element) element.clone();
        clone.classNames();
        assertEquals(element, clone);
        assertSame(element.getClass(), clone.getClass());
    }
}
